// ============================================================
//  BUILD REMINDER QUEUE
//  Mode: Run Once for All Items
//
//  Reads every row of the Appointments sheet and returns only the
//  rows that (a) fall on the target date, (b) are still live,
//  (c) have not already been reminded, and (d) have a contact
//  channel the patient has consented to.
//  It also pre-renders the SMS text and the HTML email body so the
//  messaging nodes stay trivial.
// ============================================================

// ---------- 0. Clinic configuration ----------
const CLINIC_NAME  = 'Northside Family Clinic';
const CLINIC_PHONE = '+10000000000';
const CLINIC_TZ    = 'Asia/Karachi';
const LEAD_DAYS    = 1;                 // remind 1 day before

// ---------- 1. Work out the target date in CLINIC time ----------
//  Never use new Date() here. The n8n server may run in UTC while
//  the clinic runs in PKT, which silently shifts the target day.
const nowLocal   = DateTime.now().setZone(CLINIC_TZ);
const targetDate = nowLocal.plus({ days: LEAD_DAYS }).toFormat('yyyy-MM-dd');
const runDate    = nowLocal.toFormat('yyyy-MM-dd');

// ---------- 2. Small helpers ----------
const clean  = (v) => String(v ?? '').trim();
const isTrue = (v) => clean(v).toUpperCase() === 'TRUE';

const E164  = /^\+[1-9]\d{7,14}$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const esc = (v) => clean(v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ---------- 3. Walk every row ----------
const queue = [];

for (const item of $input.all()) {
  const r = item.json;

  // 3a. date filter
  if (clean(r.appointment_date) !== targetDate) continue;

  // 3b. only live bookings
  if (clean(r.status).toLowerCase() !== 'scheduled') continue;

  // 3c. idempotency guard - never remind the same row twice
  if (clean(r.reminder_sent).toUpperCase() === 'YES') continue;

  // 3d. consent + contact validation
  const phoneOk = E164.test(clean(r.phone_e164)) && isTrue(r.consent_sms);
  const emailOk = EMAIL.test(clean(r.email))     && isTrue(r.consent_email);

  let channel = null;
  let skip_reason = null;

  const preferred = clean(r.preferred_channel).toLowerCase();
  if      (preferred === 'sms'   && phoneOk) channel = 'sms';
  else if (preferred === 'email' && emailOk) channel = 'email';
  else if (phoneOk)                          channel = 'sms';
  else if (emailOk)                          channel = 'email';
  else {
    skip_reason = (!isTrue(r.consent_sms) && !isTrue(r.consent_email))
      ? 'no_consent_on_file'
      : 'invalid_contact_details';
  }

  // 3e. human-readable date/time
  const when = DateTime.fromFormat(
    clean(r.appointment_date) + ' ' + clean(r.appointment_time),
    'yyyy-MM-dd HH:mm',
    { zone: CLINIC_TZ }
  );
  const readable_date = when.isValid
    ? when.toFormat('cccc d LLLL') : clean(r.appointment_date);
  const readable_time = when.isValid
    ? when.toFormat('h:mm a')      : clean(r.appointment_time);

  const first_name = clean(r.patient_first_name) || 'there';
  const clinician  = clean(r.clinician);
  const location   = clean(r.location);
  const apptId     = clean(r.appointment_id);

  // 3f. pre-render the SMS  (no clinical detail - see PHI note)
  const sms_text =
    CLINIC_NAME + ': Hi ' + first_name + ', reminder of your appointment on ' +
    readable_date + ' at ' + readable_time + ' with ' + clinician +
    ' (' + location + '). Ref ' + apptId +
    '. Reply C to cancel or call ' + CLINIC_PHONE + '.';

  // 3g. pre-render the email
  const email_subject =
    'Appointment reminder - ' + readable_date + ' at ' + readable_time;

  const row = (label, value, first) =>
    '<tr><td style="padding:8px;border:1px solid #dde3ec;' + (first ? 'width:34%;' : '') +
      'background:#f6faf9;font-weight:bold;">' + label + '</td>' +
      '<td style="padding:8px;border:1px solid #dde3ec;">' + value + '</td></tr>';

  const email_html =
    '<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;' +
    'margin:0 auto;color:#1f2933;line-height:1.6;">' +
      '<h2 style="margin:0 0 4px;color:#0b6b5b;">Appointment Reminder</h2>' +
      '<p style="margin:0 0 20px;color:#6b7280;font-size:13px;">' +
        esc(CLINIC_NAME) + '</p>' +
      '<p>Hi ' + esc(first_name) + ',</p>' +
      '<p>This is a reminder of your upcoming appointment.</p>' +
      '<table style="width:100%;border-collapse:collapse;font-size:14px;' +
      'margin:18px 0;">' +
        row('Date', esc(readable_date), true) +
        row('Time', esc(readable_time)) +
        row('Clinician', esc(clinician)) +
        row('Location', esc(location)) +
        row('Reference', esc(apptId)) +
      '</table>' +
      '<p>Please arrive 10 minutes early. To cancel or reschedule, call ' +
        '<strong>' + esc(CLINIC_PHONE) + '</strong> at least 24 hours ' +
        'beforehand so we can offer the slot to another patient.</p>' +
      '<p style="margin-top:22px;">Kind regards,<br><strong>' +
        esc(CLINIC_NAME) + '</strong></p>' +
      '<hr style="border:none;border-top:1px solid #e3e8ef;margin:24px 0 10px;">' +
      '<p style="font-size:11px;color:#9aa5b1;margin:0;">' +
        'Automated reminder. Please do not reply with medical information; ' +
        'this mailbox is not monitored by clinical staff.</p>' +
    '</div>';

  queue.push({
    json: {
      row_number:       r.row_number,
      appointment_id:   apptId,
      first_name,
      phone_e164:       clean(r.phone_e164),
      email:            clean(r.email),
      clinician,
      location,
      appointment_date: clean(r.appointment_date),
      readable_date,
      readable_time,
      channel,
      has_valid_contact: channel !== null,
      skip_reason,
      sms_text,
      email_subject,
      email_html,
      target_date: targetDate,
      run_date: runDate
    }
  });
}

// An empty array is a valid, healthy result: it simply means no
// appointments are scheduled for the target date.
return queue;

// ============================================================
//  SUMMARISE RUN
//  Mode: Run Once for All Items
//  Counts what happened and renders one Slack message.
// ============================================================

// Items arriving here are the rows we successfully updated.
const sentCount = $input.all().length;

// Reach back to the queue for the full picture, including skips.
const queue   = $('Build Reminder Queue').all().map(i => i.json);
const total   = queue.length;
const skipped = queue.filter(q => !q.has_valid_contact);

const bySms   = queue.filter(q => q.channel === 'sms').length;
const byEmail = queue.filter(q => q.channel === 'email').length;

// Group the skip reasons so the front desk knows what to fix.
const reasons = {};
for (const s of skipped) {
  reasons[s.skip_reason] = (reasons[s.skip_reason] || 0) + 1;
}
const reasonText = Object.entries(reasons)
  .map(([k, v]) => k.replace(/_/g, ' ') + ': ' + v)
  .join(', ') || 'none';

const runDate    = queue[0]?.run_date    ?? DateTime.now().toFormat('yyyy-MM-dd');
const targetDate = queue[0]?.target_date ?? 'n/a';

const summary =
  '*Appointment Reminder Run - ' + runDate + '*\n' +
  'Appointments on ' + targetDate + ': *' + total + '*\n' +
  'Reminders sent: *' + sentCount + '*  (SMS ' + bySms +
  ', Email ' + byEmail + ')\n' +
  'Skipped: *' + skipped.length + '*  (' + reasonText + ')';

return [{
  json: { run_date: runDate, target_date: targetDate, total,
          sent: sentCount, skipped: skipped.length,
          by_sms: bySms, by_email: byEmail, summary }
}];
